#property version   "1.01"
#property strict
#property indicator_chart_window
#property indicator_buffers 1                    // Precisamos de um buffer para a média
#property indicator_color1 Blue                  // Cor da linha da média

// Parâmetros de entrada configuráveis
input int      SMA_Period = 14;                  // Período da Média Móvel
input double   Sensibilidade = 5;                // Sensibilidade em pontos (distância para alerta)
input bool     Notificacao_Ativa = true;         // Enviar notificação no celular?

// Buffers para armazenar a média
double SMABuffer[];                              // Buffer para a média
double PreviousAlertPrice = 0;                   // Preço do último alerta (para evitar alertas repetidos)

//+------------------------------------------------------------------+
//| Função de inicialização do indicador                             |
//+------------------------------------------------------------------+
int OnInit()
  {
   // Conecta o buffer da média móvel ao gráfico
   SetIndexBuffer(0, SMABuffer, INDICATOR_DATA);
   SetIndexStyle(0, DRAW_LINE, STYLE_SOLID, 2, clrBlue);  // Configura a aparência da linha (cor, espessura)
   IndicatorSetString(INDICATOR_SHORTNAME, "SMA Alert (" + IntegerToString(SMA_Period) + ")");
   return(INIT_SUCCEEDED);
  }

//+------------------------------------------------------------------+
//| Função principal de cálculo                                      |
//+------------------------------------------------------------------+
int OnCalculate(const int rates_total,     // Número total de candles no gráfico
                const int prev_calculated, // Número de candles previamente calculados
                const datetime &time[],    // Array de horários dos candles
                const double &open[],      // Array de preços de abertura
                const double &high[],      // Array de preços máximos
                const double &low[],       // Array de preços mínimos
                const double &close[],     // Array de preços de fechamento
                const long &tick_volume[], // Array de volume de ticks
                const long &volume[],      // Array de volume de negociação
                const int &spread[])       // Array de spreads
  {
   // Certifica-se de que há dados suficientes para o cálculo
   if (rates_total <= SMA_Period) 
      return(0);

   // Calcula a média móvel simples diretamente no buffer
   SimpleMAOnBuffer(rates_total, prev_calculated, close, SMABuffer);

   // Verifica se é necessário enviar um alerta
   CheckAlerts(rates_total, close);

   return(rates_total);
  }

//+------------------------------------------------------------------+
//| Calcula a Média Móvel Simples diretamente no Buffer              |
//+------------------------------------------------------------------+
void SimpleMAOnBuffer(int rates_total, int prev_calculated, const double &price[], double &buffer[])
  {
   int start = MathMax(prev_calculated - 1, SMA_Period);  // Inicia no candle correto
   for (int i = start; i < rates_total; i++) 
     {
      double sum = 0.0;
      for (int j = 0; j < SMA_Period; j++) 
         sum += price[i - j];
      buffer[i] = sum / SMA_Period;  // Calcula a média
     }
  }

//+------------------------------------------------------------------+
//| Verifica condições para emitir alertas                          |
//+------------------------------------------------------------------+
void CheckAlerts(int rates_total, const double &price[])
  {
   // Obtém o preço atual e o valor da SMA no último candle
   double currentPrice = price[rates_total - 1];   // Preço atual
   double smaValue = SMABuffer[rates_total - 1];  // Valor da SMA no último candle

   // Calcula a distância entre o preço atual e a média
   double distance = MathAbs(currentPrice - smaValue);

   // Verifica se o preço está dentro do intervalo de sensibilidade
   if (distance <= Sensibilidade * _Point && PreviousAlertPrice != currentPrice)
     {
      // Dispara um alerta visual
      string mensagem = "O preço tocou ou chegou perto da SMA! Preço: " + DoubleToString(currentPrice, _Digits);
      Alert(mensagem);

      // Envia notificação ao celular via MetaTrader (se ativado nas configurações)
      if (Notificacao_Ativa)
         SendNotification(mensagem);

      // Atualiza o último preço alertado para evitar alertas duplicados
      PreviousAlertPrice = currentPrice;
     }
  }
```

---

### O que muda neste código?

1. **A média móvel aparece no gráfico**: 
   - Adicionamos propriedades e funções que ligam o buffer da SMA (`SMABuffer[]`) aos gráficos.
   - A linha da SMA será desenhada diretamente no gráfico com `DRAW_LINE`.
   - Você pode alterar a cor e a espessura da linha no código na configuração `SetIndexStyle`.

2. **Configurações visuais:**
   - A média é plotada em **azul** por padrão, mas você pode mudar a cor na linha onde aparece `clrBlue`.

3. **Função `SimpleMAOnBuffer`:**
   - Essa função calcula diretamente a média móvel simples e desenha o resultado no buffer `SMABuffer[]`.

4. **A lógica para notificação permanece igual**:
   - O alerta será enviado quando o preço atual tocar a média ou estiver dentro do intervalo definido por `Sensibilidade`.

---

### Instruções de Uso

1. **Salvar e compilar**:
   - Salve o código como `SMA_Alert_Touch.mq5` na pasta:
     ```
     MQL5/Indicators/
     ```
   - Compile no MetaEditor (pressione F7 para verificar se não há erros).

2. **Adicionar ao gráfico**:
   - No MetaTrader, vá para `Navegador` → `Indicadores` → `Indicadores Personalizados`.
   - Arraste o indicador para o gráfico de ativos desejado.

3. **Parâmetros configuráveis**:
   - **`SMA_Period`**: Período da média móvel (ex.: 14, 50, 200).
   - **`Sensibilidade`**: Quantidade de pontos próximos da média que devem gerar o alerta.
   - **`Notificacao_Ativa`**: Enviar notificações para o aplicativo MetaTrader no celular (ativo por padrão).

4. **Configuração de notificações no celular**:
   - Certifique-se de ter configurado corretamente o `MetaQuotes ID` no MetaTrader para que notificações sejam enviadas.

---

### Como a média se comporta no gráfico?

Agora o indicador funcionará como um indicador visual padrão e a média móvel será desenhada diretamente no gráfico. Qualquer evento (toque ou proximidade do preço em relação à média) dispara notificações.

